import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import ProfModal from './ProfModal';

/* ════════════════════════════════════════════════
   HOOK FAVORIS — utilisable dans toute l'app
════════════════════════════════════════════════ */
export function useFavoris() {
  const [favoris, setFavoris] = useState(() => {
    try { return JSON.parse(localStorage.getItem('edumatch_favoris') || '[]'); }
    catch { return []; }
  });

  const saveFavoris = useCallback((list) => {
    setFavoris(list);
    localStorage.setItem('edumatch_favoris', JSON.stringify(list));
  }, []);

  const toggleFavori = useCallback((prof) => {
    setFavoris(prev => {
      const exists = prev.some(f => f.id === prof.id);
      const next   = exists ? prev.filter(f => f.id !== prof.id) : [...prev, prof];
      localStorage.setItem('edumatch_favoris', JSON.stringify(next));
      return next;
    });
  }, []);

  const isFavori = useCallback((profId) => favoris.some(f => f.id === profId), [favoris]);

  return { favoris, toggleFavori, isFavori, saveFavoris };
}

/* ════════════════════════════════════════════════
   BOUTON FAVORI — à utiliser dans ProfCard
════════════════════════════════════════════════ */
export function FavoriButton({ prof, size = 32 }) {
  const { toggleFavori, isFavori } = useFavoris();
  const [anim, setAnim] = useState(false);
  const fav = isFavori(prof?.id);

  const handle = (e) => {
    e.stopPropagation();
    toggleFavori(prof);
    setAnim(true);
    setTimeout(() => setAnim(false), 400);
  };

  return (
    <button
      onClick={handle}
      title={fav ? 'Retirer des favoris' : 'Ajouter aux favoris'}
      style={{
        width: size, height: size, borderRadius: '50%',
        background: fav ? 'rgba(255,101,132,0.15)' : 'rgba(0,0,0,0.2)',
        border: fav ? '1px solid rgba(255,101,132,0.4)' : '1px solid rgba(255,255,255,0.15)',
        cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
        fontSize: size > 28 ? '.9rem' : '.75rem',
        transition: 'all .2s',
        transform: anim ? 'scale(1.3)' : 'scale(1)',
        backdropFilter: 'blur(4px)',
      }}
    >
      {fav ? '❤️' : '🤍'}
    </button>
  );
}

/* ════════════════════════════════════════════════
   PAGE MES FAVORIS
════════════════════════════════════════════════ */
function Stars({ n }) {
  const v = parseFloat(n) || 0;
  return (
    <span>
      {[1,2,3,4,5].map(i => <span key={i} style={{ color: i <= Math.round(v) ? '#f59e0b' : 'var(--border)', fontSize: '.85rem' }}>★</span>)}
      <span style={{ fontSize: '.75rem', color: 'var(--text2)', marginLeft: 4 }}>{v.toFixed(1)}</span>
    </span>
  );
}

export default function Favoris() {
  const navigate = useNavigate();
  const { favoris, toggleFavori, isFavori } = useFavoris();
  const [selectedProf, setSelectedProf] = useState(null);
  // Enrichir les données des favoris depuis l'API
  const [profsData, setProfsData] = useState({});

  useEffect(() => {
    if (favoris.length === 0) return;
    // Charger les données fraîches des profs favoris
    Promise.all(
      favoris.map(f => api.get(`/api/professeurs/${f.id || f.prof_id}`).catch(() => null))
    ).then(results => {
      const map = {};
      results.forEach((r, i) => {
        if (r?.data) map[favoris[i].id] = r.data;
      });
      setProfsData(map);
    });
  }, [favoris.length]);

  const getProf = (f) => profsData[f.id] || f;

  return (
    <div style={{ padding: 32, maxWidth: 1100, margin: '0 auto' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 28 }}>
        <div>
          <h1 style={{ fontFamily: 'Syne', fontSize: '1.8rem', fontWeight: 800, margin: '0 0 6px' }}>❤️ Mes professeurs favoris</h1>
          <p style={{ color: 'var(--text2)', margin: 0 }}>{favoris.length} professeur{favoris.length !== 1 ? 's' : ''} sauvegardé{favoris.length !== 1 ? 's' : ''}</p>
        </div>
        <button onClick={() => navigate('/profs')} style={{ padding: '10px 20px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 12, cursor: 'pointer', fontWeight: 700, color: '#fff', fontSize: '.88rem' }}>
          + Découvrir des profs
        </button>
      </div>

      {favoris.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '60px 20px', background: 'var(--card)', borderRadius: 24, border: '1px solid var(--border)' }}>
          <div style={{ fontSize: '3rem', marginBottom: 16 }}>🤍</div>
          <h3 style={{ fontFamily: 'Syne', margin: '0 0 10px' }}>Aucun favori pour l'instant</h3>
          <p style={{ color: 'var(--text2)', marginBottom: 24 }}>Cliquez sur le ❤️ d'un professeur pour le sauvegarder ici.</p>
          <button onClick={() => navigate('/profs')} style={{ padding: '12px 28px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 12, cursor: 'pointer', fontWeight: 700, color: '#fff' }}>
            Parcourir les professeurs
          </button>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 20 }}>
          {favoris.map(f => {
            const p   = getProf(f);
            const nom = `${p.user_prenom || ''} ${p.user_nom || ''}`.trim() || 'Professeur';
            const mats = p.tarifs_matieres ? [...new Set(p.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 3) : [];
            const fav = isFavori(p.id || f.id);

            return (
              <div key={f.id}
                style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, overflow: 'hidden', transition: 'all .25s', cursor: 'pointer' }}
                onMouseEnter={e => { e.currentTarget.style.transform='translateY(-4px)'; e.currentTarget.style.boxShadow='0 16px 40px rgba(108,99,255,0.15)'; e.currentTarget.style.borderColor='rgba(108,99,255,0.4)'; }}
                onMouseLeave={e => { e.currentTarget.style.transform='none'; e.currentTarget.style.boxShadow='none'; e.currentTarget.style.borderColor='var(--border)'; }}
              >
                {/* Bandeau */}
                <div style={{ height: 88, background: 'linear-gradient(135deg,rgba(108,99,255,.35),rgba(255,101,132,.2))', position: 'relative' }}>
                  <div style={{ position: 'absolute', top: 10, right: 10 }}>
                    <button onClick={(e) => { e.stopPropagation(); toggleFavori(p.id ? p : f); }}
                      style={{ width: 32, height: 32, borderRadius: '50%', background: 'rgba(255,101,132,0.15)', border: '1px solid rgba(255,101,132,0.4)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.9rem', transition: 'all .2s' }}
                      title="Retirer des favoris"
                    >❤️</button>
                  </div>
                  <div style={{ width: 68, height: 68, borderRadius: '50%', border: '3px solid var(--card)', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.6rem', overflow: 'hidden', position: 'absolute', bottom: -34, left: 18 }}>
                    {p.photo_url ? <img src={`http://localhost:8001${p.photo_url}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
                  </div>
                </div>

                <div style={{ padding: '42px 18px 18px' }} onClick={() => setSelectedProf(p)}>
                  <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem', marginBottom: 4 }}>{nom}</div>
                  {p.ville && <div style={{ fontSize: '.75rem', color: 'var(--text2)', marginBottom: 8 }}>📍 {p.ville}</div>}
                  <Stars n={p.note_moyenne} />

                  {mats.length > 0 && (
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, margin: '10px 0' }}>
                      {mats.map(m => <span key={m} style={{ fontSize: '.67rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20, background: 'rgba(108,99,255,0.08)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.15)' }}>{m}</span>)}
                    </div>
                  )}

                  <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
                    <button onClick={(e) => { e.stopPropagation(); setSelectedProf(p); }}
                      style={{ flex: 1, padding: '8px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 9, cursor: 'pointer', fontWeight: 700, color: '#fff', fontSize: '.8rem' }}>
                      Voir le profil
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {selectedProf && <ProfModal prof={selectedProf} onClose={() => setSelectedProf(null)} />}
    </div>
  );
}
